'use strict';
(async()=>{const main=document.getElementById('main');if(main)main.textContent='Connexion au serveur…';await window.BRAWL_SERVER_READY;for(const source of document.querySelectorAll('script[type="application/x-brawl"]'))await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=source.getAttribute('src');script.onload=resolve;script.onerror=reject;document.head.append(script);});if(window.BRAWL_CONFIG?.backend==='local'&&!window.BRAWL_CONFIG.endpoint)window.App?.toast('Le serveur sur le PC est éteint. Lance DEMARRER sur le PC puis recharge le jeu.');})().catch(()=>{document.getElementById('main').textContent='Le jeu ne peut pas démarrer. Recharge la page.';});
